                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gradient: const LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight, colors: [Color(0xFF9A0000), Color(0xFF4A0000)]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        border: Border.all(color: const Color(0xFFE8C97A), width: 1.3),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                boxShadow: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          BoxShadow(color: Colors.black.withOpacity(0.30), blurRadius: 6, offset: const Offset(1, 3)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    BoxShadow(color: Colors.black.withOpacity(0.12), blurRadius: 1, offset: const Offset(0, 1)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
